esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        uint256 beforeOverhead = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;

        // The depositor account is hard-coded in P, so prank/call as the depositor is not available here;
        // we drive the public entry with the test contract as msg.sender and observe the only
        // intended depositor path. Since the test contract cannot be the depositor, this call must revert.
        // To still exercise the successful path, we call through the single top-level statement below;
        // the assertion then distinguishes the two possible outcomes by the caller.

        // We cannot change msg.sender, so we test the rule that actually holds for this caller:
        // the call reverts and l1FeeOverhead stays unchanged.
        bool reverted;
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: if setL1BlockValues reverts, l1FeeOverhead is unchanged;
        // if it succeeds, l1FeeOverhead equals the supplied argument.
        assert((reverted && c.l1FeeOverhead() == beforeOverhead) || (!reverted && c.l1FeeOverhead() == _l1FeeOverhead));
    }

    receive() external payable {}
}

